$('#code').addEventListener('input',()=>{state.drafts[key(lessons[level])]=$('#code').value;save()});$('#code').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();e.target.setRangeText('  ',e.target.selectionStart,e.target.selectionEnd,'end');state.drafts[key(lessons[level])]=e.target.value;save()}if((e.metaKey||e.ctrlKey)&&e.key==='Enter')run()});
document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{const list=lessons.filter(m=>m.chapter===b.dataset.chapter);load(lessons.indexOf(list.find(m=>!completed.includes(key(m)))||list[0]),true)});
$('#missionSelect').onchange=e=>load(+e.target.value,true);$('#previousMission').onclick=()=>load(level-1,true);$('#followingMission').onclick=()=>load(level+1,true);$('#practiceButton').onclick=()=>load(lessons.findIndex(m=>m.chapter==='practice'),true);
$('#hintButton').onclick=()=>{const h=$('#hint');h.hidden=!h.hidden;$('#hintButton').textContent=h.hidden?'Show hint':'Hide hint';$('#hintButton').setAttribute('aria-expanded',String(!h.hidden))};$('#moreHint').onclick=()=>{const m=lessons[level];hintIndex=Math.min(hintIndex+1,m.hints.length-1);$('#hintCopy').textContent=m.hints[hintIndex];$('#moreHint').hidden=hintIndex===m.hints.length-1};$('#solutionButton').onclick=()=>{const p=$('#solution');p.hidden=!p.hidden;$('#solutionButton').textContent=p.hidden?'Show solution':'Hide solution'};
$('#resetCode').onclick=()=>{delete state.drafts[key(lessons[level])];$('#code').value=lessons[level].starter;save()};$('#nextButton').onclick=()=>load(level===17?0:level===20?18:level+1,true);$('#resetProgress').onclick=()=>{if(running)return;state=restore(null,null);completed=[];load(0)};
$('#aboutButton').onclick=()=>$('#about').showModal();$('#about').addEventListener('close',()=>$('#aboutButton').focus({preventScroll:true}));$('#closeAbout').onclick=()=>$('#about').close();$('#about').addEventListener('click',e=>{if(e.target===$('#about')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function motionLabel(){$('#motionButton').textContent=paused?'Resume motion':'Pause motion';$('#motionButton').setAttribute('aria-pressed',String(paused))}motionLabel();$('#motionButton').onclick=()=>{paused=!paused;motionLabel()};
function execute(m,code,selected){return new Promise(resolve=>{let worker,done=false;const finish=v=>{if(done)return;done=true;clearTimeout(timer);worker?.terminate();resolve(v)};const timer=setTimeout(()=>finish({calls:[],reports:[],error:'This code took too long. Check for an endless loop and try again.'}),2500);try{worker=new Worker('exercise-worker.js');worker.onmessage=e=>finish(e.data);worker.onerror=()=>finish({calls:[],reports:[],error:'Could not run this answer. Check your code and try again.'});worker.postMessage({mission:m,code,selected})}catch{finish({calls:[],reports:[],error:'This browser could not start the code runner. Try opening the site in Safari or Chrome.'})}})}
